css:
:host{--bg:#f3f1ec;--card:#fbfaf7;--ink:#1c1b19;--sub:#6a665f;--line:rgba(28,27,25,.11);--tung:#a0660f;--tungbg:rgba(168,106,18,.1);--new:#2c5b4d;--newbg:rgba(44,91,77,.1);--chip:rgba(28,27,25,.06)}
@media (prefers-color-scheme:dark){:host{--bg:#10100f;--card:#181817;--ink:#ecebe7;--sub:#a29e96;--line:rgba(255,255,255,.1);--tung:#f0b14a;--tungbg:rgba(240,165,50,.13);--new:#8fc7b3;--newbg:rgba(143,199,179,.12);--chip:rgba(255,255,255,.07)}}
*{box-sizing:border-box}:host{-webkit-text-size-adjust:100%}
.hb-docbody{margin:0;background:var(--bg);color:var(--ink);font:16px/1.72 "Pretendard Variable",Pretendard,-apple-system,BlinkMacSystemFont,"Apple SD Gothic Neo","Malgun Gothic","Segoe UI",sans-serif;word-break:keep-all;overflow-wrap:anywhere}
main{max-width:860px;margin:0 auto;padding:0 18px 80px}
header{padding:44px 0 18px}header .k{font-size:12px;letter-spacing:.14em;color:var(--sub)}
h1{font-size:30px;line-height:1.28;margin:10px 0 12px;letter-spacing:-.02em}
.lede{color:var(--sub);font-size:14.5px;margin:0}
blockquote{margin:18px 0 0;padding:12px 16px;border-left:2px solid var(--ink);background:var(--card);font-size:13.5px;color:var(--sub);border-radius:0 10px 10px 0}
nav{position:sticky;top:0;z-index:5;background:var(--bg);border-bottom:1px solid var(--line);margin:0 -18px;padding:9px 18px;display:flex;gap:6px;overflow-x:auto;scrollbar-width:none}
nav::-webkit-scrollbar{display:none}nav a{flex:none;font-size:12.5px;color:var(--ink);text-decoration:none;padding:5px 11px;border-radius:99px;background:var(--chip)}
h2{font-size:22px;letter-spacing:-.015em;margin:54px 0 6px;line-height:1.35;scroll-margin-top:56px}h2 small{display:block;font-size:13px;font-weight:500;color:var(--sub);letter-spacing:0;margin-top:2px}
h2 .g{display:inline-block;min-width:1.5em;margin-right:6px;font-weight:800}
h3{font-size:16px;margin:26px 0 8px}p{margin:10px 0}.intro{font-size:15px}
ol.sum{padding-left:22px;margin:10px 0}ol.sum li{margin:8px 0;font-size:15px}
.top{display:grid;gap:8px;margin:14px 0}.top>div{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px 14px;display:grid;grid-template-columns:28px 1fr;gap:2px 10px}
.top .n{grid-row:span 3;font-size:20px;font-weight:800;color:var(--sub)}.top b{font-size:15.5px}.top .id{font-size:11.5px;color:var(--sub);margin-left:6px;font-weight:500}.top span{font-size:13.5px}.top em{font-style:normal;font-size:12.5px;color:var(--sub)}
details.idea{background:var(--card);border:1px solid var(--line);border-radius:14px;margin:8px 0}
details.idea>summary{list-style:none;cursor:pointer;padding:13px 40px 13px 14px;position:relative;display:flex;flex-wrap:wrap;gap:5px 8px;align-items:center}
details.idea>summary::-webkit-details-marker{display:none}details.idea>summary::after{content:"+";position:absolute;right:15px;top:11px;font-size:19px;color:var(--sub)}details.idea[open]>summary::after{content:"–"}
.iid{font-size:12px;font-weight:800;color:var(--sub);min-width:28px}.ttl{font-weight:700;font-size:15.5px;margin-right:4px}
.bd{font-size:10.5px;padding:1px 7px;border-radius:99px;background:var(--chip);color:var(--sub);white-space:nowrap}.bd.nw{background:var(--newbg);color:var(--new);font-weight:700}.bd.w1{background:var(--ink);color:var(--bg)}
.ib{padding:0 14px 14px}.ib .what{margin:0 0 10px;font-size:14.5px}
dl{display:grid;grid-template-columns:92px 1fr;gap:7px 12px;margin:0;font-size:13.5px;line-height:1.6}dt{color:var(--sub);font-size:12.5px;padding-top:1px}dd{margin:0}
dd.ok{color:var(--tung);font-weight:600}.fl{display:flex;flex-wrap:wrap;gap:4px 0}.fl span{display:inline-block}.fl span:not(:last-child)::after{content:"→";margin:0 6px;color:var(--sub)}
@container hbdoc (max-width:520px){dl{grid-template-columns:1fr;gap:1px}dt{margin-top:8px}h1{font-size:25px}.hb-docbody{font-size:15.5px}}
.fig{margin:16px 0 22px;padding:14px;background:var(--card);border:1px solid var(--line);border-radius:16px;overflow:hidden}
.fig>h4{margin:0 0 2px;font-size:13.5px}.fig>.fake{font-size:11px;color:var(--sub);margin:0 0 12px}
.flow{display:block;width:100%;max-width:400px;margin:0 auto;color:var(--ink)}
.mrow{display:flex;gap:16px;flex-wrap:wrap;justify-content:center;align-items:flex-start}
.note{max-width:230px;font-size:12.5px;line-height:1.6;color:var(--sub);align-self:center}.note b{color:var(--ink)}.cap2{font-size:12.5px;color:var(--sub);margin:10px 2px 0}
.phone{width:252px;flex:none;background:#0a0a0a;border-radius:34px;padding:8px;box-shadow:0 14px 34px rgba(0,0,0,.2)}
.scr{background:#f8f8f6;color:#161616;border-radius:27px;overflow:hidden;font-size:11.5px;line-height:1.5;min-height:452px;display:flex;flex-direction:column}
.scr.dk{background:#101010;color:#ededed}.sbar{display:flex;justify-content:space-between;padding:7px 16px 2px;font-size:10px;font-weight:600;opacity:.75}
.bar{display:flex;justify-content:space-between;align-items:center;padding:8px 12px;font-weight:700;font-size:12.5px;border-bottom:1px solid rgba(0,0,0,.07)}.bar.dk{border-color:rgba(255,255,255,.09)}
.mut{color:#8a8782;font-weight:500}.mut2{color:#a8a8a8}.foot{margin-top:auto;padding:10px;text-align:center;font-size:11px;font-weight:600;border-top:1px solid rgba(0,0,0,.07)}.foot.dk{border-color:rgba(255,255,255,.09);color:#a8a8a8}
.ph{position:relative;background:linear-gradient(158deg,#57524a,#191713 72%);overflow:hidden;border-radius:4px}.ph.b{background:linear-gradient(158deg,#444d55,#101315 72%)}.ph.r{background:linear-gradient(158deg,#6a4a3a,#170f0b 72%)}
.ph svg{position:absolute;left:50%;bottom:-2%;height:86%;transform:translateX(-50%);fill:#000;opacity:.5}
.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:2px;padding:2px}
.sheet{margin:8px;padding:10px;border-radius:14px;background:#fff;box-shadow:0 2px 12px rgba(0,0,0,.08)}.sh-t{font-weight:700;font-size:12.5px;margin-bottom:7px}
.chips{display:flex;gap:5px;margin-bottom:6px}.chip{padding:3px 9px;border-radius:99px;border:1px solid #d6d3cc;font-size:10.5px}.chip.on{background:#161616;color:#fff;border-color:#161616}
.tog{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:6px 0;border-top:1px solid #eee}.tog small{color:#8a8782;font-size:10px}
.sw{flex:none;width:30px;height:18px;border-radius:9px;background:#cfccc5;position:relative}.sw::after{content:"";position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:#fff}.sw.on{background:#161616}.sw.on::after{left:14px}
.bigbtn{margin-top:8px;text-align:center;padding:8px;border-radius:10px;background:#161616;color:#fff;font-weight:700}
.pcard{position:relative;width:204px;height:363px;border-radius:14px;overflow:hidden;color:#fff;flex:none;box-shadow:0 12px 30px rgba(0,0,0,.22)}.pcard .ph{border-radius:0}
.pc-top{position:absolute;top:12px;left:14px;right:14px;font-size:9.5px;letter-spacing:.16em;opacity:.85}
.pc-bot{position:absolute;left:0;right:0;bottom:0;padding:44px 14px 10px;background:linear-gradient(transparent,rgba(0,0,0,.86) 46%)}
.pc-rank{display:inline-block;font-size:10.5px;font-weight:800;letter-spacing:.08em;border:1px solid rgba(255,255,255,.75);padding:1px 8px;border-radius:99px;margin-bottom:6px}
.pc-name{font-size:25px;font-weight:800;letter-spacing:-.01em;line-height:1.15}.pc-sub{font-size:10.5px;opacity:.85;margin-top:3px}
.pc-foot{display:flex;justify-content:space-between;font-size:8.5px;opacity:.7;margin-top:10px;padding-top:7px;border-top:1px solid rgba(255,255,255,.22)}
.pc-cta{margin-top:9px;text-align:center;padding:7px;border-radius:9px;background:#fff;color:#111;font-size:11px;font-weight:700}
.wm{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;text-align:center;font-size:13px;font-weight:700;letter-spacing:.2em;line-height:3.4;color:rgba(255,255,255,.2);transform:rotate(-24deg) scale(1.3)}
.post-h{display:flex;gap:8px;align-items:center;padding:8px 10px;font-size:11px;line-height:1.35}.post-h small{color:#8a8782}.av{flex:none;width:28px;height:28px;border-radius:50%;background:linear-gradient(135deg,#3b3833,#8c867b)}
.cnt{position:absolute;top:8px;right:8px;font-size:9.5px;background:rgba(0,0,0,.55);color:#fff;padding:1px 7px;border-radius:99px}.post-b{padding:8px 10px}.post-b p{margin:4px 0}.ic{font-size:15px;letter-spacing:.1em}
.chat{background:#eceae5}.day{text-align:center;font-size:9.5px;color:#8a8782;margin:8px 0 2px}
.me,.you{max-width:82%;margin:5px 10px;padding:7px 10px;border-radius:14px;position:relative}.me{align-self:flex-end;background:#2a2927;color:#fff;border-bottom-right-radius:4px}.you{align-self:flex-start;background:#fff;border-bottom-left-radius:4px}
.me i,.you i{display:block;font-style:normal;font-size:8.5px;opacity:.55;text-align:right;margin-top:2px}.lab{display:block;font-size:9px;color:#8a8782;margin-bottom:2px}.lab.tg2{color:#a0660f;font-weight:700}
.lnk{display:block;margin-top:6px;padding:6px;text-align:center;border-radius:8px;border:1px solid #d6d3cc;font-weight:700;font-size:11px}
.hub{background:#0f0f0f;color:#ededed;border-radius:14px;padding:12px;font-size:11.5px;line-height:1.55;width:100%;max-width:580px;margin:0 auto;font-family:inherit}
.hub .hd{display:flex;justify-content:space-between;align-items:center;gap:8px;color:#a8a8a8;font-size:11px}.hub .hd b{color:#ededed;font-size:12.5px}
.hub .t{background:#1d1d1d;border:1px solid rgba(255,255,255,.07);border-radius:10px;padding:10px;margin-top:8px}.hub small{color:#8a8a8a;font-size:10.5px}
.tg{display:inline-block;padding:1px 8px;border-radius:99px;font-size:10px;font-weight:600;border:1px solid rgba(240,165,50,.32);background:rgba(240,165,50,.13);color:#f0b14a;white-space:nowrap}
.gr{color:#8fd0a8}.rd{color:#f08a7a;font-weight:700}
.btn{display:inline-block;padding:4px 10px;border-radius:8px;background:#f2f2f2;color:#111;font-weight:700;font-size:10.5px;white-space:nowrap}.btn.g{background:transparent;border:1px solid rgba(255,255,255,.14);color:#ededed;font-weight:500}
.cand{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.cand .t{padding:7px;margin-top:8px}.cand .off{opacity:.38}.cn{font-weight:600;margin-top:6px;font-size:11px}
.cs{display:flex;gap:3px;flex-wrap:wrap;margin:4px 0}.cs em{font-style:normal;font-size:9.5px;padding:0 5px;border-radius:5px;border:1px solid rgba(255,255,255,.12)}.cs .y{color:#8fd0a8;border-color:rgba(143,208,168,.35)}.cs .n{color:#777;text-decoration:line-through}
.blur{position:absolute;top:14%;left:50%;transform:translateX(-50%);width:44%;aspect-ratio:1;border-radius:50%;background:rgba(190,190,190,.5);backdrop-filter:blur(4px);font-size:0}
.wk{display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-top:8px}.wk>div{background:#1d1d1d;border:1px solid rgba(255,255,255,.07);border-radius:8px;min-height:92px;padding:6px 4px;font-size:10px}.wk b{display:block;color:#a8a8a8;margin-bottom:4px}
.wk .it{display:block;background:#2b2b2b;border-radius:6px;padding:4px;line-height:1.35}.wk .it small{font-size:9px}.wk .emp{border-style:dashed}.al{color:#f0b14a;font-size:9.5px}
@container hbdoc (max-width:520px){.wk{grid-template-columns:repeat(4,1fr)}.cand{grid-template-columns:repeat(2,1fr)}}
.story{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.fr b{display:block;font-size:11px;margin-top:5px}.fr span{display:block;font-size:10.5px;color:var(--sub);line-height:1.35}.fr .ph{border-radius:8px}
@container hbdoc (max-width:520px){.story{grid-template-columns:repeat(3,1fr)}}
.banner{width:204px;flex:none;background:#151412;color:#f2f0ea;border-radius:8px;padding:20px 16px;text-align:center;box-shadow:0 12px 30px rgba(0,0,0,.2)}.banner small{font-size:9.5px;letter-spacing:.1em;opacity:.7}.banner h5{font-size:19px;line-height:1.35;margin:14px 0;letter-spacing:-.01em}.banner p{font-size:11px;margin:12px 0}.banner.sm h5{font-size:16px}
.qr{width:128px;height:128px;border-radius:6px;display:block;margin:0 auto}
.form{padding:10px 12px}.form label{display:block;font-size:10px;color:#8a8782;margin-top:6px}.inp{border:1px solid #d6d3cc;border-radius:8px;padding:6px 9px;background:#fff;font-weight:600}
.ck{display:flex;gap:7px;margin-top:8px;line-height:1.35}.ck i{flex:none;width:15px;height:15px;border:1.5px solid #9a968e;border-radius:4px;margin-top:1px}.ck i.on{background:#161616;border-color:#161616}.ck small,.form>small{font-size:9.5px;color:#8a8782}.form>small{display:block;margin-top:8px;line-height:1.4}
.six{display:grid;grid-template-columns:repeat(6,1fr);gap:4px;margin:8px 0 5px}@container hbdoc (max-width:520px){.six{grid-template-columns:repeat(3,1fr)}}
.facts,.chk{margin:4px 0 0;padding-left:16px}.facts li.q{color:#f0b14a}.chk{list-style:none;padding:0}.chk li{padding:5px 0 5px 20px;border-top:1px solid rgba(255,255,255,.07);position:relative}.chk li::before{content:"✓";position:absolute;left:2px;color:#8fd0a8}
.ht{width:100%;border-collapse:collapse;margin-top:8px}.ht td{padding:7px 6px;border-top:1px solid rgba(255,255,255,.07);vertical-align:top}.ht td:first-child{font-weight:600;white-space:nowrap}
.big3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:8px}.big3 div{background:#1d1d1d;border:1px solid rgba(255,255,255,.07);border-radius:10px;padding:10px;text-align:center}.big3 b{display:block;font-size:22px}.big3 span{color:#a8a8a8;font-size:10.5px}
.br{display:grid;grid-template-columns:86px 1fr 52px;gap:8px;align-items:center;padding:4px 0}.bx{position:relative;height:12px}.bx i{position:absolute;left:0;top:0;height:12px;border-radius:3px;background:#3a3a3a}.bx i.k{background:#ededed}.br em{font-style:normal;color:#a8a8a8;font-size:10.5px;text-align:right}
.live{font-size:9.5px;color:#f0b14a;font-weight:700}.res{padding:8px 10px}.rt{font-weight:700;font-size:11.5px;margin:8px 0 5px}.rt small{font-weight:500;color:#8a8a8a;margin-left:4px}.r3{display:grid;grid-template-columns:repeat(3,1fr);gap:4px}
.r3 u{position:absolute;left:5px;top:4px;text-decoration:none;font-weight:800;font-size:11px;color:#fff}.sk{aspect-ratio:3/4;border-radius:4px;background:repeating-linear-gradient(120deg,#1b1b1b,#1b1b1b 10px,#222 10px,#222 20px)}
table.tb{width:100%;border-collapse:collapse;font-size:13px;margin:10px 0;background:var(--card);border-radius:12px;overflow:hidden}.tb th,.tb td{padding:8px 10px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}.tb th{font-size:12px;color:var(--sub);font-weight:600}
.scroll{overflow-x:auto;margin:0 -18px;padding:0 18px}
.dots{letter-spacing:1px;white-space:nowrap}.dots i{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--line);margin-right:2px}.dots i.f{background:var(--ink)}.dots.rk i.f{background:var(--tung)}
.kan{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:14px 0}@container hbdoc (max-width:640px){.kan{grid-template-columns:1fr}}
.kan>div{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px}.kan h4{margin:0 0 2px;font-size:14.5px}.kan p{margin:0 0 8px;font-size:12px;color:var(--sub)}
.kan a{display:inline-block;font-size:12px;margin:2px 3px 2px 0;padding:2px 8px;border-radius:99px;background:var(--chip);color:var(--ink);text-decoration:none}.kan a b{color:var(--sub);margin-right:3px}
.rules{display:grid;gap:8px;margin:12px 0}.rules div{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px 13px;font-size:13.5px}.rules b{display:block;font-size:14px}
dl.gl{grid-template-columns:130px 1fr}@container hbdoc (max-width:520px){dl.gl{grid-template-columns:1fr}}dl.gl dt{color:var(--ink);font-weight:700;font-size:13.5px}
ol.src{padding-left:0;list-style:none;font-size:12.5px}ol.src li{padding:8px 0;border-bottom:1px solid var(--line)}ol.src b{margin-right:6px}ol.src a{color:inherit;word-break:break-all}ol.src span{color:var(--sub)}
details.fold>summary{cursor:pointer;font-weight:700;padding:10px 0}footer{margin-top:50px;font-size:12px;color:var(--sub)}
.leg{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:12.5px;color:var(--sub);margin:10px 0}/* 작은 글자 올림(작은 글자 금지) */


.bd{font-size:11px}.fig>.fake{font-size:11.5px}.sbar{font-size:10.5px}.scr{font-size:12px}.bar{font-size:13px}.day{font-size:10.5px}
.me i,.you i{font-size:10px}.lab{font-size:10.5px}.chip{font-size:11px}.tog small,.ck small,.form>small{font-size:10.5px}.form label{font-size:11px}
.hub{font-size:12px}.hub small{font-size:11px}.hub .hd{font-size:11.5px}.tg{font-size:11px}.btn{font-size:11px}.cs em{font-size:10.5px}.cn{font-size:11.5px}
.wk>div{font-size:11px}.wk .it small{font-size:10.5px}.al{font-size:10.5px}.pc-top{font-size:10.5px}.pc-sub{font-size:11px}.pc-foot{font-size:10.5px}.pc-rank{font-size:11px}
.pc-cta{font-size:12px}.cnt{font-size:10.5px}.banner small{font-size:10.5px}.banner p{font-size:12px}.br em,.big3 span{font-size:11px}.live{font-size:10.5px}.rt small{font-size:11px}
.fr b{font-size:11.5px}.fr span{font-size:11px}.foot{font-size:11.5px}.post-h{font-size:12px}.note{font-size:13px}.cap2{font-size:13px}/* 카드 안 줄 */

.ib dl{display:block}.ib .rw{display:grid;grid-template-columns:92px 1fr;gap:12px;padding:3.5px 0}
@container hbdoc (max-width:520px){.ib .rw{grid-template-columns:1fr;gap:1px;padding-top:7px}}
.ib .rw dd.ok{color:var(--tung);font-weight:600}
.ttl small{display:block;font-weight:500;font-size:12.5px;color:var(--sub);margin-top:1px}
summary .ttlw{flex:1 1 220px;min-width:0}
.gx{color:var(--sub);font-size:.88em;font-weight:400}/* 카드 그림 */

.cf{margin:4px 0 14px;padding:12px;background:var(--bg);border:1px solid var(--line);border-radius:14px;overflow:hidden}
.cf>figcaption{font-size:13.5px;font-weight:600;line-height:1.5;margin:0 0 10px}.cf>figcaption b{display:inline-block;font-size:11px;letter-spacing:.06em;padding:1px 7px;border-radius:99px;background:var(--ink);color:var(--bg);margin-right:6px;vertical-align:1px}
.cf .rdl,.cf .tbd,.cf .fk{font-size:12.5px;line-height:1.55;margin:10px 0 0;color:var(--sub)}.cf .rdl b,.cf .tbd b{color:var(--ink)}
.cf .tbd{padding:7px 10px;border-radius:10px;border:1px dashed var(--tung);color:var(--ink)}.cf .tbd b{color:var(--tung)}
.cf .fk{font-size:11.5px;opacity:.85}
.cf .hub{max-width:100%}/* 흐름 */

.fh{display:grid;grid-template-columns:repeat(var(--n),minmax(0,1fr));gap:22px;width:100%;max-width:620px;margin:0 auto;align-self:center}
.fh .st{position:relative;border-radius:12px;padding:9px 11px;background:var(--card);border:1px solid var(--line);font-size:13px;line-height:1.45}
.fh .st i{display:block;font-style:normal;font-size:11px;font-weight:800;letter-spacing:.03em;margin-bottom:3px}
.fh .st i em{font-style:normal;margin-left:6px;padding:0 6px;border-radius:99px;background:var(--tungbg);color:var(--tung);font-size:10.5px}
.fh .st:not(:last-child)::after{content:"→";position:absolute;right:-17px;top:50%;transform:translateY(-50%);color:var(--sub);font-size:15px}
.fh .c i{color:#4f6b85}.fh .o{border-color:var(--tung)}.fh .o i{color:var(--tung)}.fh .h{background:var(--ink);color:var(--bg);border-color:var(--ink)}.fh .h i{color:var(--bg);opacity:.75}
.fh .x{border-style:dashed}.fh .x i{color:var(--new)}.fh .p i{color:var(--sub)}
@media(prefers-color-scheme:dark){.fh .c i{color:#9db8d2}}
